-- Read-only post-rollout verification. Run with: supabase db query --read-only --remote=<ref> -f this-file
select 'counts' k, format('ws=%s appts=%s fin=%s subs=%s migs=%s receipts=%s', (select count(*) from public.workspaces),(select count(*) from public.appointments),(select count(*) from public.financial_entries),(select count(*) from public.subscriptions),(select count(*) from supabase_migrations.schema_migrations),(select count(*) from public.financial_receipts)) v
union all select 'paused', (select globally_paused::text from app.booking_creation_controls)
union all select 'tables_without_force_rls', coalesce(string_agg(c.relname, ','),'none') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app') and c.relkind='r' and not (c.relrowsecurity and c.relforcerowsecurity)
union all select 'anon_exec_public_fns', coalesce(string_agg(p.proname, ','),'none') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and has_function_privilege('anon', p.oid, 'execute') and p.prosecdef
union all select 'missing_rpcs', coalesce(string_agg(x, ','),'none') from unnest(array['complete_appointment_checkout','get_commissions_page','get_member_permission_editor','settle_financial_entry','get_my_permissions','pay_commission','set_commission_rule','get_commission_settings','admin_list_workspaces']) x where not exists (select 1 from pg_proc where proname=x)
union all select 'auth_cannot_exec', coalesce(string_agg(p.proname, ','),'none') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('complete_appointment_checkout','get_commissions_page','get_member_permission_editor','settle_financial_entry','get_my_permissions') and not has_function_privilege('authenticated', p.oid, 'execute');
